import{_ as r,a0 as n,w as d,s as p,ao as l,I as o,x as a,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"浅谈主机名 | LCTT x X-CMD","titleTemplate":false,"description":"浅谈主机名 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"浅谈主机名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"浅谈主机名 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211011 What is a hostname","title":"浅谈主机名","tag":"202110","desc":""},"relativePath":"202110/20211011 What is a hostname.md","filePath":"[post].md"}'),h={name:"202110/20211011 What is a hostname.md"};function c(u,e,b,m,g,k){const t=n("Link");return d(),p("div",null,[e[18]||(e[18]=l('<h1 id="浅谈主机名" tabindex="-1">浅谈主机名 <a class="header-anchor" href="#浅谈主机名" aria-label="Permalink to “浅谈主机名”">​</a></h1><blockquote><p>主机名是人类用来指代特定计算机的标签。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/19/134329lwni9tlq9h3u4f4o.jpg" alt=""></p><p>计算机有网络地址，但人类通常很难记住它们。主机名是帮助人类参考特定计算机的标签。例如，你可能不会导航到 <code>192.168.1.4</code>，而是导航到 <code>linuxlaptop</code> 或 <code>linuxlaptop.local</code>。</p><h3 id="地址和名称" tabindex="-1">地址和名称 <a class="header-anchor" href="#地址和名称" aria-label="Permalink to “地址和名称”">​</a></h3><p>所有联网的计算机（也被称为<ruby>主机<rt>host</rt></ruby>）都需要一个地址：一个与之相关的唯一数字，以使数据报文能够在它们之间进行正确的数据通信。这就是所谓的<ruby>互联网协议<rt>Internet Protocol</rt></ruby>（IP）地址。数字 <code>54.204.39.132</code> 是一个<ruby>互联网协议第四版<rt>Internet Protocol version 4</rt></ruby>（IPv4）地址。较新的 IPv6 地址要长得多，像这样：<code>2001:0db6:3c4d:0017:0000:0000:2a2f:1a2b</code>。 哇！这将是很难记住的！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr show</span></span></code></pre></div><p>计算机也可以被赋予标签。被称为<ruby>主机名<rt>hostname</rt></ruby>，这些是友好的名称，便于参考。我可以把我的计算机的主机名设置为 <code>copperhead</code>。只要这个名字在网络上是唯一的，所有其他用户和计算机都可以把 <code>copperhead</code> 作为地址，而不是 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostname -s</span></span></code></pre></div><p>你可以更新你的计算机的主机名。</p>',10)),o("p",null,[e[1]||(e[1]=a("阅读 Seth Kenlon 的文章 ",-1)),s(t,{href:"https://opensource.com/article/21/10/how-change-hostname-linux"},{default:i(()=>[...e[0]||(e[0]=[a("如何在 Linux 上更改主机名",-1)])]),_:1}),e[2]||(e[2]=a("，了解如何在 Linux 上这样做。",-1))]),e[19]||(e[19]=l('<h4 id="完全限定域名" tabindex="-1">完全限定域名 <a class="header-anchor" href="#完全限定域名" aria-label="Permalink to “完全限定域名”">​</a></h4><p>从技术上讲，主机名包括一个域名。如果我的域名是 <code>mycompany.com</code>，那么我的计算机的主机名是 <code>copperhead.mycompany.com</code>，以句点分隔。这就形成了一个<ruby>完全限定域名<rt>fully qualified domain name</rt></ruby>（FQDN）。这很重要，因为 IP 地址可以解析为 FQDN。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host.domain.topleveldomain</span></span></code></pre></div><p>例如：<code>www.example.com</code> 是一个完全限定域名。</p><p>你的域名一般已经确定了，所以你只负责提供主机部分。本文的重点是主机。</p><h4 id="名称解析" tabindex="-1">名称解析 <a class="header-anchor" href="#名称解析" aria-label="Permalink to “名称解析”">​</a></h4><p>将 IP 地址转换为相应的主机名的过程被称为名称解析。这个过程首先发生在本地主机表中。Linux 使用文件 <code>/etc/hosts</code> 来存储这个表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/hosts</span></span></code></pre></div><p>还有一个分层的、去中心化的基于网络的系统提供解析，称为<ruby>域名系统<rt>Domain Name System</rt></ruby>（DNS）。这时 FQDN 变得非常重要。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig www.opensource.com</span></span></code></pre></div><h3 id="名称的乐趣" tabindex="-1">名称的乐趣 <a class="header-anchor" href="#名称的乐趣" aria-label="Permalink to “名称的乐趣”">​</a></h3><p>为我们的计算机起名字可能很有趣。如果你有很多，你可以使用一个主题。我曾经为一家公司工作，该公司将所有的服务器都以蛇命名。</p><p>后来我工作的一家公司，我是一个数据中心经理，使用啤酒品牌。当我们收到一个新的服务器时，这很令人兴奋，因为我会给开发团队发邮件征求建议。我们大约有 100 台服务器。这些提供了一个有趣的清单，反映了公司的多样性。我们有从库尔斯和百威到阿姆斯特尔和浅粉象的一切。我们有虎牌啤酒、胜狮啤酒和札幌啤酒等等！</p><p>我们认为这很酷！然后，想象一下，当你试图记住卢云堡是拥有最多内存的虚拟化服务器，佩罗尼是 SQL 数据库服务器，喜力是新的域控制器时，会发生什么，特别是对于一个快速发展的公司的新员工。</p><h3 id="惯例" tabindex="-1">惯例 <a class="header-anchor" href="#惯例" aria-label="Permalink to “惯例”">​</a></h3><p>当然，主机名是所有者的选择，所以请尽情发挥。然而，根据环境的不同，使用容易记忆的名字或基于命名惯例的名字可能更有意义，因为这些名字有利于描述主机。</p><h4 id="有用的名字" tabindex="-1">有用的名字 <a class="header-anchor" href="#有用的名字" aria-label="Permalink to “有用的名字”">​</a></h4><p>如果你想放弃有趣的东西，并对你的系统进行有益的命名，也许可以考虑它们的功能。数据库服务器可以被命名为 <code>database1</code>、<code>database2</code>、<code>database3</code> 等等。Web 服务器可以命名为 <code>webserver1</code>、<code>webserver2</code> 等等。</p><h4 id="位置名称" tabindex="-1">位置名称 <a class="header-anchor" href="#位置名称" aria-label="Permalink to “位置名称”">​</a></h4><p>我在许多客户那里使用了一种技术，用一组字符的位置来命名服务器主机，这些字符描述了该系统的一个方面，有助于识别。例如，如果我正在为内政部（DOI）开发一个业务流程管理（BPM）系统，我就会在命名规则中加入他们的缩写词。</p><p>此外，就像许多大型企业、金融机构和政府一样，他们可能有不同的数据中心，位于不同的地理位置，以达到性能或灾难恢复的目的。因此，比如说，位于北美大陆东海岸的数据中心被称为 ED（East Data center），而位于西海岸的数据中心则是 WD（West Data center）。</p><p>所有这些信息将汇集到一个名称中，如 <code>doibpm1ed</code> 或 <code>doibpm1wd</code>。因此，虽然这些名字看起来不长，但在这个项目上工作的人可以很容易地识别它们的目的和位置，而且这个名字甚至可以对潜在的恶意者混淆它们的用途。换句话说，业主可以选择只对内部人员有意义的命名方式</p><h3 id="互联网标准" tabindex="-1">互联网标准 <a class="header-anchor" href="#互联网标准" aria-label="Permalink to “互联网标准”">​</a></h3><p>有几个标准管理着主机名。你可以在<ruby>互联网工程任务组<rt>Internet Engineering Task Force</rt></ruby>（IETF）维护的<ruby>意见征求<rt>Requests for Comment</rt></ruby>（RFC）中找到这些标准。由此，请遵守以下规定：</p><ul><li>主机名的长度应该在 1 到 63 个 ASCII 字符之间</li><li>一个 FQDN 的最大长度为 253 个 ASCII 字符</li><li>不区分大小写</li><li>允许的字符：<code>a</code> 到 <code>z</code>，<code>0</code> 到 <code>9</code>，<code>-</code>（连字符），和 <code>_</code>（下划线）。</li></ul><p>我希望这篇文章能帮助你澄清主机名。玩得开心，发挥创意。</p><hr>',27)),o("p",null,[e[4]||(e[4]=a("via: ",-1)),s(t,{href:"https://opensource.com/article/21/10/what-hostname"},{default:i(()=>[...e[3]||(e[3]=[a("https://opensource.com/article/21/10/what-hostname",-1)])]),_:1})]),o("p",null,[e[9]||(e[9]=a("作者：",-1)),s(t,{href:"https://opensource.com/users/alanfdoss"},{default:i(()=>[...e[5]||(e[5]=[a("Alan Formy-Duval",-1)])]),_:1}),e[10]||(e[10]=a(" 选题：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[6]||(e[6]=[a("lujun9972",-1)])]),_:1}),e[11]||(e[11]=a(" 译者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[7]||(e[7]=[a("geekpi",-1)])]),_:1}),e[12]||(e[12]=a(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[8]||(e[8]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[15]||(e[15]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[13]||(e[13]=[a("LCTT",-1)])]),_:1}),e[16]||(e[16]=a(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[14]||(e[14]=[a("Linux中国",-1)])]),_:1}),e[17]||(e[17]=a(" 荣誉推出",-1))])])}const C=r(h,[["render",c]]);export{x as __pageData,C as default};
